/** Real alarm draft journeys against private stores and a silent scheduling port. No alarm or preview output. */
public final class NightDialAlarmFlowTest {
 private final Instrumentation i=InstrumentationRegistry.getInstrumentation();private final Context c=i.getTargetContext();private final UiDevice d=UiDevice.getInstance(i);
 private interface Journey{void run(Scene scene)throws Exception;}
 private final class Scene implements AutoCloseable{
  final String database="night-alarm-"+UUID.randomUUID()+".db";final Records.Factory records=Records.factory;final AlarmScheduling.Port scheduling=AlarmScheduling.port;final java.util.function.LongSupplier clock=AlarmSkips.clock;final java.util.function.Supplier<ZoneId> zone=AlarmSkips.zone;final TimeZone originalZone=TimeZone.getDefault();final Map<String,?> preferences=new HashMap<>(Prefs.of(c).getAll());final AtomicInteger schedules=new AtomicInteger();final List<Activity> owned=new CopyOnWriteArrayList<>();final Application app=(Application)c.getApplicationContext();final AudioManager audio=(AudioManager)c.getSystemService(Context.AUDIO_SERVICE);final int volume=audio.getStreamVolume(AudioManager.STREAM_ALARM);
  final Application.ActivityLifecycleCallbacks life=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle s){owned.add(a);}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle s){}public void onActivityDestroyed(Activity a){}};
  Scene()throws Exception{assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",d.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertNull(SleepSoundService.snapshot());Records.factory=ctx->new Store(ctx,database);AlarmScheduling.port=new AlarmScheduling.Port(){public boolean allowed(Context context){return true;}public void schedule(Context context,Alarm alarm){schedules.incrementAndGet();}};AlarmSkips.clock=()->ZonedDateTime.of(2026,10,30,22,14,0,0,ZoneId.of("Asia/Riyadh")).toInstant().toEpochMilli();AlarmSkips.zone=()->ZoneId.of("Asia/Riyadh");TimeZone.setDefault(TimeZone.getTimeZone("Asia/Riyadh"));Appearance.save(c,false,0,0,false,false);app.registerActivityLifecycleCallbacks(life);}
  Store store(){return new Store(c,database);}
  Alarm seed(){Alarm alarm=new Alarm(1);alarm.label="Daybreak";alarm.enabled=true;alarm.hour=7;alarm.minute=0;alarm.volume=80;alarm.days.addAll(Set.of(1,2,3,4,5));try(Store store=store()){store.save(alarm);}return alarm;}
  <T extends Activity>T activity(Class<T> type){return type.cast(owned.stream().filter(a->type.isInstance(a)&&!a.isFinishing()&&!a.isDestroyed()).reduce((a,b)->b).orElseThrow());}
  <T extends Activity>T launch(Class<T> type,Intent intent)throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(type.getName(),null,false);try{c.startActivity(intent.putExtra("visualReview",true).putExtra("verificationLabel","Design review · isolated alarm draft").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Activity found=monitor.waitForActivityWithTimeout(5000);assertNotNull(type.getSimpleName(),found);return type.cast(found);}finally{i.removeMonitor(monitor);}}
  void recreate(Class<? extends Activity> type)throws Exception{Activity before=activity(type);Instrumentation.ActivityMonitor monitor=i.addMonitor(type.getName(),null,false);try{i.runOnMainSync(before::recreate);assertNotNull(monitor.waitForActivityWithTimeout(5000));}finally{i.removeMonitor(monitor);}d.waitForIdle();}
  void unchanged(String json){try(Store store=store()){assertEquals(json,store.alarm(1).json().toString());}assertEquals(0,schedules.get());assertEquals(volume,audio.getStreamVolume(AudioManager.STREAM_ALARM));assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertNull(SleepSoundService.snapshot());}
  public void close()throws Exception{d.pressHome();i.runOnMainSync(()->owned.forEach(a->{if(!a.isDestroyed())a.finish();}));i.waitForIdleSync();long until=SystemClock.elapsedRealtime()+6000;while(owned.stream().anyMatch(a->!a.isDestroyed())&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(40);assertTrue("All scene windows destroyed",owned.stream().allMatch(Activity::isDestroyed));app.unregisterActivityLifecycleCallbacks(life);Records.factory=records;AlarmScheduling.port=scheduling;AlarmSkips.clock=clock;AlarmSkips.zone=zone;TimeZone.setDefault(originalZone);SharedPreferences.Editor restore=Prefs.of(c).edit();for(String key:List.of(Appearance.AUTO,Appearance.THEME,Appearance.SIZE,Appearance.MOTION,Appearance.CONTRAST)){Object value=preferences.get(key);if(value instanceof Boolean)restore.putBoolean(key,(Boolean)value);else if(value instanceof Integer)restore.putInt(key,(Integer)value);else restore.remove(key);}assertTrue(restore.commit());assertEquals("No unrelated preference writes",preferences,Prefs.of(c).getAll());assertEquals(volume,audio.getStreamVolume(AudioManager.STREAM_ALARM));c.deleteDatabase(database);}
 }
 private void scene(Journey journey)throws Exception{try(Scene scene=new Scene()){try{journey.run(scene);}catch(Exception|AssertionError failure){File dir=new File(c.getExternalFilesDir(null),"verification");dir.mkdirs();d.takeScreenshot(new File(dir,"night-dial-alarm-failure.png"));d.dumpWindowHierarchy(new File(dir,"night-dial-alarm-failure.xml"));throw failure;}}}
 private UiObject2 text(String value){UiObject2 found=d.wait(Until.findObject(By.text(value)),5000);assertNotNull(value,found);return found;}
 private UiObject2 desc(String value)throws Exception{UiObject2 found=d.wait(Until.findObject(By.desc(value)),1200);if(found==null){new UiScrollable(new UiSelector().scrollable(true)).scrollIntoView(new UiSelector().description(value));found=d.wait(Until.findObject(By.desc(value)),5000);}assertNotNull(value,found);return found;}
 private void tap(String value)throws Exception{UiObject2 found=d.wait(Until.findObject(By.text(value)),1200);if(found==null){new UiScrollable(new UiSelector().scrollable(true)).scrollIntoView(new UiSelector().text(value));found=text(value);}found.click();d.waitForIdle();}
 private void capture(String name)throws Exception{NightDialCapture.frame(i,c,d,"alarm-"+name);}
 private UiObject2 name(){UiObject2 found=d.wait(Until.findObject(By.clazz("android.widget.EditText").desc("Alarm name")),5000);assertNotNull(found);return found;}
 private <T extends View>T find(View view,Class<T> type){if(type.isInstance(view))return type.cast(view);if(view instanceof ViewGroup group)for(int n=0;n<group.getChildCount();n++){T found=find(group.getChildAt(n),type);if(found!=null)return found;}return null;}
 @Test public void nameRepeatAndDirtyBackRestoreWithoutSaving()throws Exception{scene(scene->{
  Alarm alarm=scene.seed();String original=alarm.json().toString();try(Store store=scene.store()){Alarm early=Alarm.read(alarm.json());early.id=3;early.label="Early shift";early.hour=6;store.save(early);}
  scene.launch(MainActivity.class,new Intent(c,MainActivity.class).putExtra("destination",1));desc("Edit Early shift");List<UiObject2> edit=d.findObjects(By.descStartsWith("Edit "));assertTrue(edit.size()>=2);assertEquals("Edit Early shift",edit.get(0).getContentDescription());capture("list");desc("Edit Daybreak").click();text("Save alarm");capture("editor");desc("Name").click();name().setText("Morning desk");capture("name-draft");scene.recreate(AlarmEditorActivity.class);assertEquals("Morning desk",name().getText());capture("name-restored");scene.unchanged(original);tap("Use name");text("Save alarm");desc("Repeat rule").click();text("Repeat rule");desc("Interval").click();desc("Repeat interval days").setText("0");tap("Use repeat rule");text("Choose an interval from 1 to 365 days.");capture("repeat-invalid");scene.recreate(AlarmRepeatActivity.class);assertEquals("0",desc("Repeat interval days").getText());capture("repeat-restored");desc("Repeat interval days").setText("3");capture("repeat-interval");tap("Use repeat rule");text("Save alarm");assertFalse(desc("Monday").isEnabled());assertFalse(desc("Sunday").isEnabled());capture("repeat-parent");scene.unchanged(original);desc("Back").click();text("Discard alarm changes?");capture("discard");scene.recreate(AlarmEditorActivity.class);text("Discard alarm changes?");capture("discard-restored");tap("Keep editing");assertTrue(d.wait(Until.gone(By.text("Discard alarm changes?")),5000));assertTrue(d.hasObject(By.text("Morning desk")));desc("Back").click();text("Discard alarm changes?");tap("Discard");assertTrue(d.wait(Until.gone(By.text("Save alarm")),5000));scene.unchanged(original);
 });}
 @Test public void routineOrderingGentleAndSnoozeStayInDraftUntilSave()throws Exception{scene(scene->{
  Alarm alarm=scene.seed();String original=alarm.json().toString();scene.launch(AlarmEditorActivity.class,new Intent(c,AlarmEditorActivity.class).putExtra("alarm",original));text("Save alarm");desc("Challenges").click();text("Save routine");capture("routine");tap("Browse all tasks");desc("Search task types").setText("Memory");text("1 matching task");capture("task-search");desc("Configure Memory").click();text("Add Memory");capture("task-config");scene.unchanged(original);tap("Add Memory");text("Save routine");desc("Order or remove task 2").click();tap("Move up");assertTrue(d.wait(Until.hasObject(By.desc("Edit task 1 Memory")),5000));capture("routine-ordered");tap("Save routine");text("Save alarm");scene.unchanged(original);tap("More alarm settings");tap("Gentle wake-up");desc("Volume ramp").click();text("Volume ramp");capture("ramp-picker");tap("2 min");desc("Sound delay").click();tap("30 sec");AlarmEditorActivity gentleEditor=scene.activity(AlarmEditorActivity.class);i.runOnMainSync(()->{AlarmRampChart chart=find(gentleEditor.getWindow().getDecorView(),AlarmRampChart.class);assertNotNull(chart);assertTrue(chart.getContentDescription().toString().contains("80 percent after 120 seconds"));assertTrue(chart.getContentDescription().toString().contains("after 30 seconds"));});capture("gentle");scene.recreate(AlarmEditorActivity.class);text("Gentle wake-up");capture("gentle-restored");scene.unchanged(original);tap("Use wake-up settings");desc("Back").click();text("Save alarm");desc("Snooze").click();desc("Maximum snoozes").click();tap("3");desc("Shorten each snooze").click();final AlarmEditorActivity current=scene.activity(AlarmEditorActivity.class);i.runOnMainSync(()->{AlarmSnoozePreview preview=find(current.getWindow().getDecorView(),AlarmSnoozePreview.class);assertNotNull(preview);String description=preview.getContentDescription().toString();assertTrue(description.contains("Snooze 1: 5 minutes"));assertTrue(description.contains("Snooze 2: 4 minutes"));assertTrue(description.contains("Snooze 3: 3 minutes"));});capture("snooze");scene.recreate(AlarmEditorActivity.class);text("Snooze & backup");assertTrue(desc("Shorten each snooze").isChecked());capture("snooze-restored");tap("Use snooze settings");text("Save alarm");scene.unchanged(original);tap("Save alarm");assertTrue(d.wait(Until.gone(By.text("Save alarm")),5000));try(Store store=scene.store()){Alarm saved=store.alarm(1);assertEquals(List.of("Memory","Math"),saved.challenges().tasks.stream().map(task->task.type).toList());assertEquals(120,saved.rampSeconds);assertEquals(30,saved.soundDelaySeconds);assertTrue(saved.shortenSnoozes);assertEquals(3,saved.snoozeLimit);assertEquals(Set.of(1,2,3,4,5),saved.days);assertEquals(80,saved.volume);}assertEquals(1,scene.schedules.get());assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertNull(SleepSoundService.snapshot());capture("saved");
 });}
}
